import itertools

def get_all_perfect_matchings(n):
    nodes = list(range(n))
    def generate(remaining):
        if not remaining:
            yield []
            return
        first = remaining[0]
        for i in range(1, len(remaining)):
            second = remaining[i]
            for rest in generate(remaining[1:i] + remaining[i+1:]):
                yield [(first, second)] + rest
    return list(generate(nodes))

def solve_f(n):
    pms = get_all_perfect_matchings(n)
    pm_sets = [set(pm) for pm in pms]

    # We want to find the smallest size of a set of disjoint perfect matchings
    # that is maximal.
    from itertools import combinations

    for size in range(1, n):
        for combo in combinations(range(len(pm_sets)), size):
            # Check if the matchings in the combo are disjoint
            edges = set()
            possible = True
            for idx in combo:
                for edge in pm_sets[idx]:
                    # Normalize edge
                    e = tuple(sorted(edge))
                    if e in edges:
                        possible = False
                        break
                    edges.add(e)
                if not possible:
                    break

            if possible:
                # Check if it's maximal
                is_maximal = True
                for idx in range(len(pm_sets)):
                    if idx in combo:
                        continue
                    # Check if pm_sets[idx] is disjoint from the current set of edges
                    can_add = True
                    for edge in pm_sets[idx]:
                        e = tuple(sorted(edge))
                        if e in edges:
                            can_add = False
                            break
                    if can_add:
                        is_maximal = False
                        break
                if is_maximal:
                    return size
    return None

