def solve_f_recursive(n):
    nodes = list(range(n))
    def generate_pms(remaining):
        if not remaining:
            yield []
            return
        first = remaining[0]
        for i in range(1, len(remaining)):
            second = remaining[i]
            for rest in generate_pms(remaining[1:i] + remaining[i+1:]):
                yield [(first, second)] + rest

    pms = list(generate_pms(nodes))
    edge_to_idx = {}
    idx_counter = 0
    for i in range(n):
        for j in range(i+1, n):
            edge_to_idx[(i, j)] = idx_counter
            idx_counter += 1

    pm_masks = []
    for pm in pms:
        mask = 0
        for u, v in pm:
            mask |= (1 << edge_to_idx[tuple(sorted((u, v)))])
        pm_masks.append(mask)

    def is_maximal(current_mask, current_size):
        for pm_mask in pm_masks:
            if (current_mask & pm_mask) == 0:
                return False
        return True

    # Iterative deepening for the smallest size
    def find_maximal(current_mask, start_idx, current_size, target_size):
        if current_size == target_size:
            if is_maximal(current_mask, current_size):
                return True
            return False

        for i in range(start_idx, len(pm_masks)):
            if (current_mask & pm_masks[i]) == 0:
                if find_maximal(current_mask | pm_masks[i], i + 1, current_size + 1, target_size):
                    return True
        return False

    for size in range(1, n):
        if find_maximal(0, 0, 0, size):
            return size
    return None

